function MillSailClothTensionerMaker.init() MillSailClothTensionerMaker.ironStock=14; MillSailClothTensionerMaker.bronzeStock=12; MillSailClothTensionerMaker.woodStock=12; MillSailClothTensionerMaker.leatherStock=8; MillSailClothTensionerMaker.silverStock=8; MillSailClothTensionerMaker.goldStock=6; MillSailClothTensionerMaker.jewelStock=4; MillSailClothTensionerMaker.pearlStock=4; MillSailClothTensionerMaker.productStock={}; MillSailClothTensionerMaker.buildings={}; MillSailClothTensionerMaker.maker=nil; MillSailClothTensionerMaker.activeMaking={}; MillSailClothTensionerMaker.totalProducts=0; MillSailClothTensionerMaker.dayTimer=0; print("[MillSailClothTensionerMaker] Royal Mill Sail Cloth Tensioner Maker System initialized (6 products, 4 buildings)") end
function MillSailClothTensionerMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; MillSailClothTensionerMaker.maker={name=n or ("Napenjalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napenjalec najet: %s (spretnost: %d)",MillSailClothTensionerMaker.maker.name,s),"success") end; return true end
function MillSailClothTensionerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function MillSailClothTensionerMaker.build(id) local ok,e=MillSailClothTensionerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(MillSailClothTensionerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function MillSailClothTensionerMaker.getQualityBonus() local b=0; for _,bd in ipairs(MillSailClothTensionerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function MillSailClothTensionerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and MillSailClothTensionerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and MillSailClothTensionerMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and MillSailClothTensionerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and MillSailClothTensionerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and MillSailClothTensionerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and MillSailClothTensionerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and MillSailClothTensionerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and MillSailClothTensionerMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #MillSailClothTensionerMaker.buildings==0 then return false,"Potrebna napenjalna delavnica" end; if not MillSailClothTensionerMaker.maker then return false,"Potreben napenjalec" end; return true end
function MillSailClothTensionerMaker.make(pt,qty) qty=qty or 1; local ok,e=MillSailClothTensionerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then MillSailClothTensionerMaker.ironStock=MillSailClothTensionerMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then MillSailClothTensionerMaker.bronzeStock=MillSailClothTensionerMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then MillSailClothTensionerMaker.woodStock=MillSailClothTensionerMaker.woodStock-d.woodCost*qty end; if d.leatherCost then MillSailClothTensionerMaker.leatherStock=MillSailClothTensionerMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then MillSailClothTensionerMaker.silverStock=MillSailClothTensionerMaker.silverStock-d.silverCost*qty end; if d.goldCost then MillSailClothTensionerMaker.goldStock=MillSailClothTensionerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then MillSailClothTensionerMaker.jewelStock=MillSailClothTensionerMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then MillSailClothTensionerMaker.pearlStock=MillSailClothTensionerMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if MillSailClothTensionerMaker.maker then t=math.max(1,t-math.floor(MillSailClothTensionerMaker.maker.skill/13)) end; table.insert(MillSailClothTensionerMaker.activeMaking,{id="millsailclothtensioner_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function MillSailClothTensionerMaker.completeMaking(m) local q=1.0+(MillSailClothTensionerMaker.getQualityBonus()/100); if MillSailClothTensionerMaker.maker then q=q+(MillSailClothTensionerMaker.maker.skill/140) end; q=math.min(2.5,q); MillSailClothTensionerMaker.productStock[m.productType]=(MillSailClothTensionerMaker.productStock[m.productType] or 0)+m.quantity; MillSailClothTensionerMaker.totalProducts=MillSailClothTensionerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if MillSailClothTensionerMaker.maker then MillSailClothTensionerMaker.maker.itemsMade=MillSailClothTensionerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then MillSailClothTensionerMaker.maker.skill=math.min(100,MillSailClothTensionerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Napenjalec izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"millsailclothtensioner.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function MillSailClothTensionerMaker.update(dt) if not _G.state then return end; MillSailClothTensionerMaker.dayTimer=MillSailClothTensionerMaker.dayTimer+dt; if MillSailClothTensionerMaker.dayTimer>=30 then MillSailClothTensionerMaker.dayTimer=0; for i=#MillSailClothTensionerMaker.activeMaking,1,-1 do local m=MillSailClothTensionerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then MillSailClothTensionerMaker.completeMaking(m); table.remove(MillSailClothTensionerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(MillSailClothTensionerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if MillSailClothTensionerMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
